import { Link } from "@tanstack/react-router"
import { useState, type ReactNode } from "react"
import { useIsMobile } from "@/shared/lib/use-mobile"
import { Button } from "@/shared/ui/button"
import { ArrowLeftIcon, MaximizeIcon } from "@/shared/ui/icon"
import { PaneResizeHandle } from "@/shared/ui/pane-resize-handle"
import { InboxIllustration, PageState } from "@/shared/ui/page-state"
import { usePeekClose } from "./use-peek-close"

/** 처리 목록의 목록 칸 너비(px): 가장 넓게(최대값으로) 연다. 끌어 줄인 너비는 이 화면에 있는 동안만 남는다. */
const LIST_WIDTH = { min: 288, max: 560 }

/**
 * 처리 목록(받은 요청 · 알림 · 승인 대기)의 두 칸: 왼쪽 목록(288~560px로 끌어 조절)과 오른쪽 상세 칸(InboxPane).
 * 상세 칸은 늘 있고 고른 것이 없으면 고르라는 빈 상태다. 휴대폰은 목록만 보이고 항목은 자기 페이지로 연다.
 */
export function InboxLayout({ list, detail, listLabel = "목록", detailLabel = "내용" }: {
  list: ReactNode; detail: ReactNode; listLabel?: string; detailLabel?: string
}) {
  const isMobile = useIsMobile()
  const [width, setWidth] = useState(LIST_WIDTH.max)
  const resize = (next: number) => setWidth(Math.round(Math.min(LIST_WIDTH.max, Math.max(LIST_WIDTH.min, next))))
  if (isMobile) return <>{list}</>
  return (
    <div data-slot="inbox-layout" className="flex min-h-0 min-w-0 flex-1 overflow-hidden">
      {/* check-ui: allow-style 목록 칸 너비는 사용자가 끌어 정한 값이다. */}
      <section aria-label={listLabel} className="flex min-h-0 max-w-[58%] shrink-0 flex-col" style={{ width: `${width / 16}rem` }}>{list}</section>
      <PaneResizeHandle label={`${listLabel} 너비`} value={width} min={LIST_WIDTH.min} max={LIST_WIDTH.max} onChange={resize} />
      <section aria-label={detailLabel} className="flex min-h-0 min-w-0 flex-1 flex-col">{detail}</section>
    </div>
  )
}

/**
 * 처리 목록의 상세 칸. 줄을 누르면(어디를 눌러도, usePeekRows의 openOnClick) 이 칸에 그 항목이 열린다. 머리에는 ← 닫기
 * (고른 것 없음으로) · 항목 이름 · 페이지로 열기, Esc로도 닫고 닫으면 초점을 그 줄로 돌린다. 고른 것이 없으면 empty의 안내.
 */
export function InboxPane({ id, title, pageHref, onClose, empty, children }: {
  /** 고른 항목. 없으면 빈 상태. */
  id?: string
  title?: string
  pageHref?: string
  onClose: () => void
  /** 고른 것이 없을 때의 안내. 예: { title: "알림을 선택해 주세요" } */
  empty: { title: string; description?: string }
  children?: ReactNode
}) {
  usePeekClose(id, onClose)
  if (!id) {
    return (
      <section aria-label="고른 항목" className="flex min-h-0 flex-1 flex-col overflow-y-auto bg-background pt-16">
        <PageState kind="empty" isCompact illustration={<InboxIllustration />} title={empty.title} description={empty.description} />
      </section>
    )
  }
  return (
    <section role="complementary" aria-label={`미리보기: ${title ?? ""}`} className="flex min-h-0 flex-1 flex-col bg-background">
      <header className="flex h-13 shrink-0 items-center gap-1 border-b px-2">
        <Button variant="ghost" size="icon-sm" aria-label="고른 항목 닫기" title="닫기 (Esc)" onClick={onClose}><ArrowLeftIcon /></Button>
        <h2 className="min-w-0 flex-1 truncate text-sm font-semibold">{title}</h2>
        {pageHref && (
          <Button variant="ghost" size="icon-sm" aria-label="페이지로 열기" title="페이지로 열기" nativeButton={false} render={<Link to={pageHref} />}>
            <MaximizeIcon />
          </Button>
        )}
      </header>
      <div className="flex min-h-0 flex-1 flex-col overflow-y-auto">{children}</div>
    </section>
  )
}

import { Link } from "@tanstack/react-router"
import type { ReactNode } from "react"
import { Button } from "@/shared/ui/button"
import { MaximizeIcon, XIcon } from "@/shared/ui/icon"
import { usePeekClose } from "./use-peek-close"

/**
 * 목록과 그 옆 칸(미리보기 · 옆 패널)을 나란히 두는 틀(옛 Page의 aside 자리). 목록 쪽(Page)은 남은 폭을 쓰고 칸은 자기 폭을 정한다.
 * 칸은 머리부터 바닥까지 목록과 따로 스크롤한다. aside가 없으면 목록만 그린다(휴대폰은 usePeek이 id를 비워 늘 목록만).
 */
export function PeekLayout({ aside, children }: { aside?: ReactNode; children: ReactNode }) {
  return (
    <div data-slot="peek-layout" className="flex min-h-0 min-w-0 flex-1">
      <div className="flex min-w-0 flex-1 flex-col">{children}</div>
      {aside}
    </div>
  )
}

/**
 * 목록 옆 미리보기(작업 목록): 목록을 가리지 않고(비모달) 본문의 45%를 쓴다. 머리에는 대상 이름 · 페이지로 열기 · 닫기,
 * Esc로도 닫고(입력 칸 · 뜬 창 안의 Esc는 제외), 닫으면 초점을 미리보던 줄(data-peek-row)로 돌린다.
 * 줄 누르기는 페이지로 가고 미리보기는 Space · 줄의 단추로 연다(usePeekRows). 본문에는 상세와 같은 부품을 넣는다:
 * 칸이 컨테이너라 DetailLayout은 좁은 모양(한 줄 알약)이 된다. PeekLayout의 aside 자리에 둔다.
 */
export function PeekPanel({ id, title, pageHref, onClose, children }: {
  id: string; title: string; pageHref: string; onClose: () => void; children: ReactNode
}) {
  usePeekClose(id, onClose)
  return (
    <section role="complementary" aria-label={`미리보기: ${title}`}
      className="flex w-[45%] min-w-80 shrink-0 flex-col border-l bg-background">
      <header className="flex h-13 shrink-0 items-center gap-2 border-b pr-2 pl-4">
        <h2 className="min-w-0 flex-1 truncate text-sm font-semibold">{title}</h2>
        <Button variant="ghost" size="icon-sm" aria-label="페이지로 열기" title="페이지로 열기" nativeButton={false} render={<Link to={pageHref} />}>
          <MaximizeIcon />
        </Button>
        <Button variant="ghost" size="icon-sm" aria-label="미리보기 닫기" title="닫기 (Esc)" onClick={onClose}><XIcon /></Button>
      </header>
      <div className="flex min-h-0 flex-1 flex-col overflow-y-auto">{children}</div>
    </section>
  )
}

import { useEffect, useRef } from "react"

/** 줄이 담은 링크(없으면 줄 자체). 미리보기를 닫은 뒤 초점이 돌아갈 곳이다. */
export const rowFocusTarget = (row: HTMLElement | null | undefined) =>
  row?.matches("a[href]") ? row : row?.querySelector<HTMLElement>("a[href]") ?? row ?? undefined

/** 입력 중이거나 뜬 창(대화상자 · 바텀시트 · 메뉴) 안의 Esc는 그것이 받는다. */
const OWNS_ESCAPE = "input, textarea, select, [contenteditable='true'], [role=dialog], [role=alertdialog], [role=menu], [role=listbox]"

/**
 * 미리보기 칸의 닫기 약속: 열려 있는 동안 Esc로 닫고, 닫히면(또는 다른 항목으로 바뀌면) 초점을 그 줄(data-peek-row)로 돌린다.
 * 줄이 남아 있고 초점이 갈 곳을 잃었을 때만 돌린다(닫기 단추가 사라져 body로 떨어진 경우).
 */
export function usePeekClose(id: string | undefined, onClose: () => void) {
  const latest = useRef(onClose)
  latest.current = onClose
  useEffect(() => {
    if (!id) return undefined
    const keydown = (event: KeyboardEvent) => {
      if (event.key !== "Escape" || event.defaultPrevented) return
      if ((event.target as HTMLElement | null)?.closest(OWNS_ESCAPE)) return
      latest.current()
    }
    window.addEventListener("keydown", keydown)
    return () => {
      window.removeEventListener("keydown", keydown)
      requestAnimationFrame(() => {
        if (document.activeElement && document.activeElement !== document.body) return
        rowFocusTarget(document.querySelector<HTMLElement>(`[data-peek-row="${CSS.escape(id)}"]`))?.focus()
      })
    }
  }, [id])
}

import type { KeyboardEvent, MouseEvent } from "react"
import { useIsMobile } from "@/shared/lib/use-mobile"
import type { Peek } from "@/shared/lib/use-peek"
import { rowFocusTarget } from "./use-peek-close"

const rowOf = (target: EventTarget) => (target as HTMLElement).closest<HTMLElement>("[data-peek-row]")

/**
 * 미리보기를 여는 목록의 줄 다루기. 목록을 감싼 요소에 돌려준 props를 펼치고, 줄마다 data-peek-row={id}와 링크 하나를 둔다.
 * - openOnClick(처리 목록): 줄을 그냥 누르면 옆 칸에 연다(처음은 기록을 쌓고 옮길 때는 바꾼다). 보조 키 · 가운데 단추는 링크대로 새 탭.
 * - 아니면(작업 목록): 줄 누르기는 링크대로 페이지로 가고, 줄 링크에 초점을 두고 Space로 미리보기를 열고 닫는다.
 * - ↑ ↓: 이웃 줄로 초점을 옮기고, 미리보기가 열려 있으면 그 줄로 바꾼다.
 * 휴대폰은 옆 칸이 없어 링크(그 페이지)를 그대로 따른다.
 */
export function usePeekRows(peek: Peek, { openOnClick = false }: { openOnClick?: boolean } = {}) {
  const isMobile = useIsMobile()
  const onClickCapture = (event: MouseEvent<HTMLElement>) => {
    if (!openOnClick || isMobile || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return
    const row = rowOf(event.target)
    // 줄 안의 다른 단추(별표 · … 메뉴)는 자기 일을 한다.
    if (!row || (event.target as HTMLElement).closest("button, [role=button]")) return
    event.preventDefault()
    const id = row.dataset.peekRow!
    if (peek.id !== id) peek.open(id)
  }
  const onKeyDown = (event: KeyboardEvent<HTMLElement>) => {
    const row = rowOf(event.target)
    if (!row || isMobile) return
    const id = row.dataset.peekRow!
    if (event.key === " " && !openOnClick && event.target instanceof HTMLAnchorElement) {
      event.preventDefault()
      if (peek.id === id) peek.close()
      else peek.open(id)
      return
    }
    if (event.key !== "ArrowDown" && event.key !== "ArrowUp") return
    const rows = [...(event.currentTarget.querySelectorAll<HTMLElement>("[data-peek-row]"))]
    const next = rows[rows.indexOf(row) + (event.key === "ArrowDown" ? 1 : -1)]
    if (!next) return
    event.preventDefault()
    rowFocusTarget(next)?.focus()
    if (peek.id) peek.move(next.dataset.peekRow!)
  }
  return { onClickCapture, onKeyDown }
}
